const std = @import("std");

pub fn main() !void {
    var arr = [_]i32{ 64, 34, 25, 12, 22, 11, 90 };

    for (0..arr.len) |_| {
        var swapped = false;
        for (0..arr.len - 1) |j| {
            if (arr[j] > arr[j + 1]) {
                const temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }

    for (arr) |val| {
        std.debug.print("{} ", .{val});
    }
    std.debug.print("\n", .{});
}
